var calculateEdgeLength = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
var calculateEdgeCost = (level, edge) => Math.ceil(edge.length * level.costPerUnit);
var calculateTotalCost = (edges) => edges.reduce((sum, e) => sum + e.cost, 0);
var canAffordEdge = (level, edges, candidate) => calculateTotalCost(edges.filter((e) => e.isPlayerBuilt)) + candidate.cost <= level.budget;
